      "rank": 1,
      "ballot_id": "B050",
      "proposed_laureates": [
        "Alexandre Blais",
        "Robert J. Schoelkopf",
        "Steven M. Girvin"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED established a powerful and broadly adopted way to couple superconducting artificial atoms to microwave fields, enabling precise studies of light–matter interaction and a major route to quantum information processing.",
        "attribution": "Blais developed the theoretical architecture, Schoelkopf led key experimental demonstrations, and Girvin contributed foundational theory. The field grew through many groups, so the division of early conceptual and experimental credit deserves careful review.",
        "maturity": "The platform has been experimentally established and developed over decades, with reproducible control and measurement across laboratories.",
        "uncertainties": [
          "The 2025 recognition of foundational superconducting-circuit physics could affect the timing or scope of a prize for circuit QED.",
          "My close professional ties to this research area call for particular care in judging its significance and credit."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Alexei Kitaev",
        "John Preskill",
        "Sergey Bravyi"
      ],
      "assessment": {
        "nobel_worthiness": "Topological quantum error correction and surface codes gave quantum computing a concrete, scalable framework for protecting information against local errors, with deep connections to topology and many-body physics.",
        "attribution": "Kitaev's code constructions and the contributions of Preskill and Bravyi to the theory and development of fault-tolerant quantum computation form a strong trio. The wider field includes important parallel work by other researchers.",
        "maturity": "The theoretical framework is well established, and experimental platforms have demonstrated increasingly capable error correction, though large-scale fault tolerance remains a future achievement.",
        "uncertainties": [
          "The eventual impact of surface codes depends on achieving practical fault-tolerant operation at scale."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Roman Schnabel"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light makes quantum fluctuations a controllable resource and improves precision measurements beyond the standard quantum limit, with clear fundamental and experimental importance.",
        "attribution": "Caves provided key theoretical foundations, Kimble helped establish squeezed-light experiments, and Schnabel advanced robust implementations including gravitational-wave detection. Credit should reflect the substantial contributions of other experimental groups as well.",
        "maturity": "The physics is thoroughly confirmed, and squeezed light is now used in precision instruments, including gravitational-wave observatories.",
        "uncertainties": [
          "The contribution of enabling technologies and multiple teams makes the boundary of a three-person award difficult to draw."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices with ultracold atoms turned controlled quantum simulation of strongly correlated matter into an experimental discipline, linking atomic physics to central problems in condensed matter.",
        "attribution": "Zoller helped establish the theoretical vision, while Bloch and Greiner led influential experimental realizations. Tilman Esslinger also made major contributions, so selecting three names from this broad development is difficult.",
        "maturity": "The platform has produced reproducible results across laboratories and continues to improve its control and range of accessible many-body phenomena.",
        "uncertainties": [
          "The field's central scientific results and the distinction between simulation and solution of difficult material problems continue to develop.",
          "The proposed attribution excludes a major experimental contributor."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Alfred Y. Cho",
        "Federico Capasso",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum cascade laser created a new kind of semiconductor laser based on intersubband transitions, opening tunable mid- and far-infrared sources with lasting scientific and technological impact.",
        "attribution": "Cho's contributions to semiconductor heterostructure growth and the work of Capasso and Faist on the device concept and its realization make a compelling attribution, though the development involved a broader team.",
        "maturity": "The device principle has been repeatedly confirmed and developed into a versatile, widely used class of lasers.",
        "uncertainties": [
          "The relative credit for conception, materials growth, and the first working device should be assessed carefully."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals and photonic band gaps showed how periodic structure can control the allowed propagation of light, establishing a major direction in optics and nanophotonics.",
        "attribution": "Yablonovitch and John independently articulated influential routes to photonic band-gap control. Russell's photonic-crystal-fiber work was also consequential but represents a related, distinct development.",
        "maturity": "The underlying effects are well established and have enabled extensive research and practical optical structures.",
        "uncertainties": [
          "The broad label combines theoretical proposals and several experimental realizations whose relationship and credit need careful definition."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Frans Pretorius",
        "John G. Baker",
        "Manuela Campanelli"
      ],
      "assessment": {
        "nobel_worthiness": "Numerical relativity made it possible to calculate the strong-field dynamics and gravitational-wave signals of merging black holes, enabling reliable interpretation of a major new observational regime.",
        "attribution": "Pretorius achieved a decisive breakthrough in stable merger simulations, while Baker and Campanelli led independent approaches that confirmed and extended the result. The collective nature of the field complicates a narrow attribution.",
        "maturity": "The methods have been validated against observations and are central to gravitational-wave astronomy.",
        "uncertainties": [
          "The proposed discovery includes multiple breakthroughs and a large subsequent community effort, making the boundaries of individual credit uncertain."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks combined ultracold atoms and ultrastable lasers to reach extraordinary frequency accuracy, with important consequences for precision measurement and tests of fundamental physics.",
        "attribution": "Katori and Ye developed complementary leading approaches that established the field. The proposed pairing reflects that parallel progress, while the broader clock community also contributed substantially.",
        "maturity": "The method is experimentally mature, reproducible, and already supports demanding measurements of time and frequency.",
        "uncertainties": [
          "The distinction between the initial invention, subsequent performance milestones, and later applications may affect the appropriate scope of recognition."
        ]
      }
    }
  ]
